#define NOMINMAX
#include <windows.h>
#include <shellapi.h>
#include <shlobj.h>
#include <iiGUI/DesktopCommon.h>
#include <cstring>

namespace ii::gui {
namespace {
std::wstring wide(std::string_view text){if(text.empty())return {};int n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,text.data(),int(text.size()),nullptr,0);if(!n)throw std::invalid_argument("Invalid UTF-8 desktop text");std::wstring value(std::size_t(n),L'\0');MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,text.data(),int(text.size()),value.data(),n);return value;}
std::string utf8(std::wstring_view text){if(text.empty())return {};int n=WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,text.data(),int(text.size()),nullptr,0,nullptr,nullptr);if(!n)throw std::invalid_argument("Invalid native UTF-16 desktop text");std::string value(std::size_t(n),'\0');WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,text.data(),int(text.size()),value.data(),n,nullptr,nullptr);return value;}
class Clipboard final{public:Clipboard(){if(!OpenClipboard(nullptr))throw std::runtime_error("Clipboard is busy");}~Clipboard(){CloseClipboard();}};
void put(UINT format,const void* bytes,std::size_t size){auto memory=GlobalAlloc(GMEM_MOVEABLE,size);if(!memory)throw std::bad_alloc();auto pointer=GlobalLock(memory);if(!pointer){GlobalFree(memory);throw std::runtime_error("Cannot lock clipboard allocation");}std::memcpy(pointer,bytes,size);GlobalUnlock(memory);if(!SetClipboardData(format,memory)){GlobalFree(memory);throw std::runtime_error("Cannot publish clipboard data");}}
std::vector<std::uint8_t> bytes(UINT format,std::size_t maximum){auto memory=GetClipboardData(format);if(!memory)return {};const auto size=GlobalSize(memory);if(size>maximum)throw std::length_error("Clipboard data exceeds its byte budget");auto* p=static_cast<const std::uint8_t*>(GlobalLock(memory));if(!p)return {};std::vector<std::uint8_t> value(p,p+size);GlobalUnlock(memory);return value;}
std::string text(UINT format,std::size_t maximum){auto data=bytes(format,maximum*2+2);if(data.size()%2)throw std::runtime_error("Invalid UTF-16 clipboard length");auto* first=reinterpret_cast<const wchar_t*>(data.data());auto count=data.size()/2;std::size_t length=0;while(length<count&&first[length])++length;if(length==count&&!data.empty())throw std::runtime_error("Unterminated clipboard text");return utf8({first,length});}
}
core::Result<ClipboardContent> read_clipboard(){try{Clipboard lock;ClipboardContent value;value.text=text(CF_UNICODETEXT,1024*1024);value.url=text(RegisterClipboardFormatW(L"UniformResourceLocatorW"),8192);
    if(auto drop=GetClipboardData(CF_HDROP)){const auto count=DragQueryFileW(static_cast<HDROP>(drop),0xffffffff,nullptr,0);if(count>256)throw std::length_error("Clipboard file count exceeds its budget");for(UINT i=0;i<count;++i){const auto size=DragQueryFileW(static_cast<HDROP>(drop),i,nullptr,0);if(size>32768)throw std::length_error("Clipboard path is too long");std::wstring path(std::size_t(size)+1,L'\0');DragQueryFileW(static_cast<HDROP>(drop),i,path.data(),size+1);path.resize(size);value.files.push_back(utf8(path));}}
    for(auto [type,mime]:{std::pair{L"PNG","image/png"},std::pair{L"image/tiff","image/tiff"},std::pair{L"JFIF","image/jpeg"}}){value.image=bytes(RegisterClipboardFormatW(type),64*1024*1024);if(!value.image.empty()){value.image_mime=mime;break;}}
    if(value.image.empty()){auto dib=bytes(CF_DIBV5,64*1024*1024-14);if(dib.empty())dib=bytes(CF_DIB,64*1024*1024-14);if(dib.size()>=40){const auto read=[&](std::size_t at){std::uint32_t n=0;std::memcpy(&n,dib.data()+at,4);return n;};const auto header=read(0),compression=read(16),colors=read(32);std::uint16_t bits=0;std::memcpy(&bits,dib.data()+14,2);std::uint64_t offset=14+header;if(header==40&&(compression==3||compression==6))offset+=compression==6?16:12;if(bits<=8)offset+=std::uint64_t(colors?colors:1U<<bits)*4;if(header<=dib.size()&&offset<=dib.size()+14){value.image.resize(dib.size()+14);auto* output=value.image.data();output[0]='B';output[1]='M';const auto size=std::uint32_t(value.image.size()),start=std::uint32_t(offset);std::memcpy(output+2,&size,4);std::memcpy(output+10,&start,4);std::copy(dib.begin(),dib.end(),output+14);value.image_mime="image/bmp";}}}
    if(!detail::valid_clipboard(value))return core::fail(core::ErrorCode::invalid_argument,"Clipboard contains invalid desktop data");return value;
}catch(...){return core::fail(core::ErrorCode::failed,"Cannot read the native clipboard",std::current_exception());}}
core::Result<void> write_clipboard(const ClipboardContent& value){if(!detail::valid_clipboard(value))return core::fail(core::ErrorCode::invalid_argument,"Invalid clipboard data");try{Clipboard lock;if(!EmptyClipboard())throw std::runtime_error("Cannot clear the clipboard");if(!value.text.empty()){auto data=wide(value.text);put(CF_UNICODETEXT,data.c_str(),(data.size()+1)*2);}if(!value.url.empty()){auto data=wide(value.url);put(RegisterClipboardFormatW(L"UniformResourceLocatorW"),data.c_str(),(data.size()+1)*2);}if(!value.files.empty()){std::wstring names;for(const auto& path:value.files){names+=wide(path);names+=L'\0';}names+=L'\0';std::vector<std::uint8_t> data(sizeof(DROPFILES)+names.size()*2);DROPFILES header{DWORD(sizeof(DROPFILES)),{},FALSE,TRUE};std::memcpy(data.data(),&header,sizeof(header));std::memcpy(data.data()+sizeof(header),names.data(),names.size()*2);put(CF_HDROP,data.data(),data.size());}if(!value.image.empty()){const wchar_t* type=value.image_mime=="image/png"?L"PNG":value.image_mime=="image/tiff"?L"image/tiff":value.image_mime=="image/bmp"?L"image/bmp":L"JFIF";put(RegisterClipboardFormatW(type),value.image.data(),value.image.size());}return {};}catch(...){return core::fail(core::ErrorCode::failed,"Cannot write the native clipboard",std::current_exception());}}
core::Result<void> open_external_url(std::string_view value){if(!detail::valid_external_url(value))return core::fail(core::ErrorCode::invalid_argument,"Expected a web, mail, or Society account URL");try{auto url=wide(value);SHELLEXECUTEINFOW info{sizeof(info)};info.fMask=SEE_MASK_NOCLOSEPROCESS|SEE_MASK_FLAG_NO_UI;info.lpVerb=L"open";info.lpFile=url.c_str();info.nShow=SW_SHOWNORMAL;if(!ShellExecuteExW(&info))throw std::runtime_error("Windows could not open the URL");if(info.hProcess)CloseHandle(info.hProcess);return {};}catch(...){return core::fail(core::ErrorCode::failed,"Cannot open the native URL",std::current_exception());}}
}
